/// <summary>
/// COC for table AgreementLine
/// Added for CB202 Sales quota by Akshay
/// </summary>
[ExtensionOf(tableStr(AgreementLine))]
final class METAgreementLine_Extension
{
}

Method.Source:
    /// <summary>
    /// Gets the remaining qty/amount to be fulfilled by sales order line for given agreement line
    /// </summary>
    /// <returns>Remaining qty/amount to be fulfilled</returns>
    public real metGetAgreementLineRemaining()
    {
        #AgreementsRemains
        container fulfillmentValues = AgreementLine::calculateFulfillmentForLine(this);

        return conPeek(fulfillmentValues, #RemainingIndex);
    }
